import { Progress as BaseProgress } from "@base-ui/react/progress";
import type { ComponentPropsWithoutRef, ElementType } from "react";
import { cn } from "../../lib/cn";
import "../../styles/progress.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

export interface ProgressProps extends StaticClass<typeof BaseProgress.Root> {
  /** Visible label above the bar, and the accessible name. */
  label?: string;
  /** Show the percentage on the right of the label. */
  showValue?: boolean;
}

/** Determinate progress bar. Pass `value` from 0 to 100, or leave it out for indeterminate. */
export function Progress({ label, showValue = false, className, value, ...props }: ProgressProps) {
  return (
    <BaseProgress.Root value={value} className={cn("eui-progress", className)} {...props}>
      {label || showValue ? (
        <div className="eui-progress__meta">
          {label ? <BaseProgress.Label className="eui-progress__label">{label}</BaseProgress.Label> : null}
          {showValue ? <BaseProgress.Value className="eui-progress__value" /> : null}
        </div>
      ) : null}
      <BaseProgress.Track className="eui-progress__track">
        <BaseProgress.Indicator className="eui-progress__indicator" />
      </BaseProgress.Track>
    </BaseProgress.Root>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Progress. Base UI sets the indicator width inline (width: N%), so the fill animates
   width. Only the width moves; the track and label stay still. */

.eui-progress {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.eui-progress__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-size: 13px;
}

.eui-progress__label {
  font-weight: 500;
  color: var(--eui-color-fg);
}

.eui-progress__value {
  color: var(--eui-color-fg-muted);
  font-variant-numeric: tabular-nums;
}

.eui-progress__track {
  position: relative;
  height: 6px;
  overflow: hidden;
  border-radius: var(--eui-radius-full);
  background-color: var(--eui-color-hover);
}

.eui-progress__indicator {
  position: absolute;
  top: 0;
  bottom: 0;
  background-color: var(--eui-color-accent);
  border-radius: inherit;
  transition: width var(--eui-duration-base) var(--eui-easing-out);
}

@media (prefers-reduced-motion: reduce) {
  .eui-progress__indicator {
    transition: none;
  }
}
